const identifyTaskDB=[{"s":"Exige que A participe en hacer disparar a B.","type":"El postulado de Hebb (1949)"},{"s":"Dice que basta con dispararse a la vez.","type":"El eslogan de 1992"},{"s":"Decide el signo del cambio según quién dispara primero.","type":"El orden de disparo"},{"s":"Las decenas de milisegundos en que el cambio ocurre.","type":"La ventana temporal"},{"s":"Un grupo de células que se enciende en conjunto.","type":"La asamblea de células"},{"s":"Producir la respuesta y comprobarla enseguida.","type":"La práctica activa"},{"s":"Tener el video puesto mientras se hace otra cosa.","type":"La exposición pasiva"},{"s":"Se gana lo practicado y nada más.","type":"La cláusula de especificidad"},{"s":"Fortalecer una conexión.","type":"Potenciación"},{"s":"Debilitar una conexión al invertir el orden.","type":"Depresión"}];
const classifyTaskDB=[{"w":"A participa en disparar a B","gen":"Postulado","n":"Exige causa y dirección","g":"1949","t":"Hebb"},{"w":"Lo que dispara junto se cablea junto","gen":"Eslogan","n":"Solo exige coincidencia","g":"1992","t":"Löwel y Singer"},{"w":"A antes que B","gen":"Orden","n":"La conexión se refuerza","g":"Dentro de la ventana","t":"Potenciación"},{"w":"A después que B","gen":"Orden","n":"La conexión se debilita","g":"Dentro de la ventana","t":"Depresión"},{"w":"Decirlo sin mirar y comprobar","gen":"Práctica","n":"Produce y corrige","g":"Activa","t":"Cablea lo que se busca"},{"w":"Audio de fondo en el bus","gen":"Práctica","n":"No produce nada","g":"Pasiva","t":"Solo coincidencia"},{"w":"La corrección en el mismo minuto","gen":"Corrección","n":"Se engancha con el intento","g":"A tiempo","t":"Refuerza"},{"w":"La corrección ocho días después","gen":"Corrección","n":"Llega sola, sin enganche","g":"Tarde","t":"No refuerza"},{"w":"Las ratas sueltas por la casa","gen":"Evidencia","n":"Resolvieron mejor","g":"1947","t":"Hebb"},{"w":"La ventana de milisegundos","gen":"Evidencia","n":"Medida en cultivo","g":"1998","t":"Bi y Poo"}];
const completeTaskDB=[{"s":"Hebb publicó su postulado en ___.","opts":["1949","1992","1998"],"ans":"1949"},{"s":"El postulado exige que A ___ en hacer disparar a B.","opts":["participe","coincida","espere"],"ans":"participe"},{"s":"El eslogan es de Löwel y ___.","opts":["Singer","Poo","Hebb"],"ans":"Singer"},{"s":"Si A dispara después que B, la conexión se ___.","opts":["debilita","refuerza","rompe"],"ans":"debilita"},{"s":"La ventana de Bi y Poo se cuenta en ___.","opts":["milisegundos","minutos","días"],"ans":"milisegundos"},{"s":"La regla refuerza el acierto y también el ___.","opts":["error","premio","descanso"],"ans":"error"},{"s":"Mirar mucho cablea la destreza de ___.","opts":["reconocer","fabricar","vender"],"ans":"reconocer"},{"s":"Se gana lo ___ y nada más.","opts":["practicado","leído","pagado"],"ans":"practicado"}];
const explainQuestions=[{"q":"Escribe el postulado de Hebb con tus palabras y señala las cuatro piezas que lo componen.","ans":"Cuando el axón de una célula A está lo bastante cerca de una célula B para excitarla y participa de forma repetida o persistente en hacerla disparar, ocurre un cambio de crecimiento o metabólico en una de las dos células, o en las dos, que aumenta la eficacia de A para disparar a B. Las cuatro piezas son: cercanía (A puede excitar a B), participación (A toma parte en encenderla, que es lo que introduce la causa), repetición (de forma repetida o persistente) y dirección (crece la eficacia de A hacia B, no al revés). Quitar cualquiera de las cuatro cambia el significado; quitar la participación es lo que produce el eslogan."},{"q":"¿Por qué «lo que dispara junto se cablea junto» no es una versión corta del postulado, sino otra afirmación?","ans":"Porque «junto» significa simultaneidad y el postulado pide participación. Que dos células estén activas a la vez no dice nada: en un cerebro despierto hay millones activas en cualquier instante. El postulado exige que una contribuya a encender a la otra, y eso trae dos cosas que la simultaneidad no trae: una causa y un orden temporal, porque para ayudar a encender algo hay que llegar antes. Además, la frase no es de Hebb: la formulación es de Löwel y Singer, en Science, en 1992, y la rima famosa es de Carla Shatz, del mismo año. En la práctica, quien cree el eslogan pone las cosas juntas y espera; quien entiende el postulado hace producir y corrige."},{"q":"¿Qué añadieron Markram (1997) y Bi y Poo (1998) al postulado, y qué limitación hay que declarar al citarlos?","ans":"Añadieron el reloj. Midieron que el signo del cambio depende del orden de los disparos: si A dispara unas decenas de milisegundos antes que B la conexión se refuerza, y si dispara después se debilita. Es la plasticidad dependiente del orden de disparo, y confirma la dirección que el postulado ya pedía. La limitación que hay que declarar es dónde se midió: en rodajas de tejido y en neuronas en cultivo, que es donde se puede medir bien. Su peso exacto en un animal despierto aprendiendo tareas de la vida real sigue siendo materia de discusión, y decirlo forma parte de citar honestamente."},{"q":"Explica por qué veinte años de escribir con dos dedos no mejoran la mecanografía.","ans":"Porque la regla refuerza lo que se repite y no distingue entre acierto y error. Veinte años son repetición de sobra, así que el postulado se cumplió al pie de la letra: lo que quedó firmemente cableado fue el método viejo, con su error incluido. Lo que nunca hubo fue un intento distinto con su corrección detrás, que es lo único capaz de encadenar una manera nueva. De ahí sale la consecuencia incómoda: practicar sin corrección es la forma más segura de volverse muy bueno en algo que se hace mal, y mejorar obliga a ir más lento que la costumbre para que quepa la corrección."},{"q":"¿Qué se le cableó a Wílmer en quince años de mirar el torno de su abuelo, y por qué no le sirvió al sentarse?","ans":"Se le cableó mirar, y muy bien. Después de quince años era excelente reconociendo una olla bien centrada, distinguiendo el barro demasiado húmedo y viendo venir un error antes de que ocurriera. Eso es exactamente lo que practicó. Lo que no practicó ni una vez fue mover las manos sobre el barro, así que esa destreza no se cableó, porque nada de lo que él hacía participaba en el resultado. Es la cláusula de especificidad: el cambio es específico de lo practicado. Mirar cablea mirar; hacer cablea hacer."},{"q":"Una aplicación cobra L 250 al mes citando el eslogan y firmando a Hebb. Escribe las dos preguntas que la descartan.","ans":"La primera pregunta es de fuente: ¿la frase que citan es de quien dicen? No lo es. El eslogan es de Löwel y Singer (1992) con la rima de Carla Shatz, y lo que Hebb escribió en 1949 no promete nada parecido. Una cita mal atribuida en la publicidad es un dato comprobable sobre el vendedor, no sobre el cerebro. La segunda pregunta es de especificidad: ¿el juego mejora la vida o mejora el juego? El cambio es específico de lo practicado, así que quien practica un juego se vuelve bueno en ese juego. La condición con que sí se pagaría ese dinero es practicar la tarea real que se quiere mejorar, porque ahí lo específico juega a favor."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

