function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Angelly pone videos de inglés mientras ordena su cuarto, dos horas al día durante un mes. Al mes siguiente sigue sin poder pedir un vaso de agua en inglés y concluye que no tiene oído."},{"txt":"Una aplicación de entrenamiento cerebral ofrece suscripción familiar por L 250 al mes y anuncia, en letras grandes, «lo que dispara junto se cablea junto», atribuido a Donald Hebb."},{"txt":"Una maestra que usa M.E.T.A.S recoge las tareas el viernes y las devuelve corregidas el lunes siguiente. Los alumnos miran la nota, guardan la hoja y repiten el mismo error a la semana."},{"txt":"Jael se sabe la tabla del siete de corrido y no falla ninguna, pero tarda cinco segundos cuando le preguntan siete por ocho suelto, porque tiene que cantar desde el principio."},{"txt":"El autor lleva más de veinte años escribiendo a computadora con dos dedos y mirando el teclado, muchas horas al día, y no ha mejorado nada en la última década."},{"txt":"Alguien propone poner «lo que dispara junto se cablea junto» como lema en la portada de las guías de maestro de M.E.T.A.S, porque es corto y suena a ciencia."},{"txt":"En M.E.T.A.S se discute si el cuestionario de cada misión debe ir todo al final, como examen, o repartido: unas preguntas al abrir y otras después de cada bloque."},{"txt":"Una academia ofrece inglés para las dos niñas por L 1,200 al mes. La familia decide ir a mirar una clase antes de decidir, en vez de preguntar por el método."}];
const critCaseQuestions=["1. ¿Qué produce quien practica en este caso, y qué solo recibe sin producir nada?","2. ¿Quién corrige, y cuánto tarda la corrección en llegar desde el intento?","3. ¿En qué orden quedan el intento y su consecuencia, y qué dice el postulado sobre ese orden?","4. ¿Qué quedará cableado si esto se repite un mes, y qué UNA cosa se cambia para que la regla juegue a favor?"];
const critCaseGuides=["Se empieza separando producción de recepción, que es la separación que el eslogan no permite hacer. Producir es decir, escribir, tocar, resolver o intentar algo por cuenta propia; recibir es tener el material delante mientras avanza solo. La pregunta útil no es cuántas horas hubo, sino cuántas veces salió algo de las manos o de la boca de quien practica. Un caso con muchas horas y cero producción es coincidencia pura, y el postulado no premia la coincidencia: premia que algo de lo que uno hace participe en el resultado.","Después se busca la corrección y se le mide el retraso. Corrección es cualquier cosa que diga si el intento salió bien: una persona, una respuesta tapada, una grabación que se vuelve a oír, el resultado visible de la acción. Lo que importa no es su severidad ni su extensión, sino cuánto tarda en llegar desde el intento, porque una corrección que llega días después llega sola y no se engancha con nada: quien la recibe ya no tiene delante lo que hizo ni por qué lo hizo.","Luego se pone en fila el intento y su consecuencia. El postulado tiene dirección, de A hacia B, y la fisiología le añadió el reloj: Markram (1997) y Bi y Poo (1998) mostraron que unas decenas de milisegundos deciden si la conexión se refuerza o se debilita, según quién dispara primero. Traducido a la práctica: intentar y después comprobar no es lo mismo que comprobar y después copiar, aunque las dos cosas ocurran en la misma tarde con el mismo material. Ver la respuesta antes de intentar deja al alumno reconociendo, no produciendo.","Y todo caso termina igual: se dice qué quedará cableado si la escena se repite un mes, recordando que la regla no distingue acierto de error y que se gana lo practicado y nada más. Después se cambia UNA sola cosa, la más barata, casi siempre la misma: convertir un rato de recepción en un rato de producción con comprobación inmediata. No hace falta corregir más; hace falta corregir antes. Y se vuelve a mirar a la semana, porque una decisión sin segunda medición es una opinión con fecha."];

const critErrorBank=[{"txt":"\"Llevo sesenta horas de video en inglés, así que algo se me habrá quedado\".","g1":"Sesenta horas de coincidencia: el sonido y la tarea doméstica ocurrieron a la vez, y ninguna participó en encender a la otra. Es exactamente el «junto» del eslogan, y el postulado pide participación.","g2":"Se cambian veinte minutos de video por veinte minutos de producir: repetir en voz alta, contestar, escribir, y comprobar enseguida. Diez minutos así valen más que dos horas de fondo."},{"txt":"\"Como dijo Hebb, lo que dispara junto se cablea junto\".","g1":"Hebb no dijo eso. La formulación es de Löwel y Singer, en Science, en 1992, y la rima famosa es de Carla Shatz, del mismo año. Lo que Hebb escribió en 1949 pide que A participe en hacer disparar a B.","g2":"Se cita la frase real con su fuente y se explica qué cambia el lunes: con el eslogan uno pone las cosas juntas y espera; con el postulado uno hace producir y corrige enseguida."},{"txt":"\"Repitió el ejercicio cien veces, ya le tiene que salir\".","g1":"Cien veces qué. La repetición no es un mérito sino un multiplicador, y multiplica lo que encuentra: si encuentra el error, lo multiplica con la misma diligencia con que multiplicaría el acierto.","g2":"Se baja la velocidad hasta que quepa la corrección y se nombra el fallo en voz alta antes del intento siguiente. Doce intentos mirados enseñan más que cien a ciegas."},{"txt":"\"Devuelvo las tareas corregidas la semana siguiente, así las reviso con calma\".","g1":"La corrección vale por su cercanía en el tiempo, no por su calidad de redacción. A los ocho días el alumno ya no tiene delante lo que hizo, así que la corrección llega sola y no se encadena con ningún intento.","g2":"Cinco preguntas comprobadas en el momento enseñan más que veinte devueltas el lunes. Por eso el cuestionario va dentro de la misión y no al final del trimestre."},{"txt":"\"Este juego entrena el cerebro, así que va a mejorar en todo\".","g1":"La cláusula de especificidad lo niega: se gana lo practicado y nada más. Quien practica un juego se vuelve bueno en ese juego, igual que quien mira quince años se vuelve bueno en reconocer.","g2":"Ese mismo dinero y esas mismas horas se ponen en la tarea real que se quiere mejorar, porque ahí la especificidad juega a favor en vez de en contra."},{"txt":"\"Ya vi el tutorial dos veces, mañana lo hago\".","g1":"Ver el modelo antes de intentar deja al que aprende reconociendo el procedimiento, no produciéndolo, y el orden importa: primero las manos, después el modelo.","g2":"Se intenta primero con lo que se tenga, se falla, y solo entonces se mira el tutorial, que ahora corrige algo concreto en vez de acompañar a nadie."}];

const critDecisionBank=["Angelly quiere seguir con sus dos horas de video en inglés: ¿se le prohíbe, se le deja, o se le cambia algo? ¿Qué exactamente, y cuánto tiempo dura el cambio?","La aplicación de L 250 al mes espera respuesta esta semana: ¿qué dos preguntas se le hacen, y qué respuesta la descarta?","La maestra pregunta cómo corregir mejor: ¿se le pide más detalle en las correcciones o algo distinto? ¿Qué, y por qué?","Jael tarda en siete por ocho: ¿se le manda cantar la tabla más veces o se cambia el ejercicio? ¿A cuál, y qué se mide para saber si funcionó?","El papá quiere aprender a escribir con diez dedos sin dejar de trabajar: ¿qué se hace con los veinte años de costumbre, y por qué al principio va a escribir más lento?","Alguien insiste con el eslogan para la portada de las guías de maestro: ¿se acepta, se rechaza, o se acepta con condición? ¿Cuál sería esa condición?","Hay que decidir dónde va el cuestionario de las misiones de M.E.T.A.S: ¿todo al final o repartido? ¿Con qué límite, y por qué ese límite?","La familia sale de mirar la clase de inglés de L 1,200: ¿qué dos números se apuntaron durante la visita, y qué se decide con ellos?"];
const critDecisionGuide='La decisión correcta en esta etapa sigue siempre el mismo orden. Primero se separa lo que se produce de lo que solo se recibe, porque el eslogan no permite hacer esa separación y el postulado la exige: hay que contar cuántas veces sale algo de las manos o de la boca de quien practica, no cuántos minutos duró la escena. Después se le mide el retraso a la corrección, que puede ser una persona, una respuesta tapada, una grabación o el resultado visible de la acción, y lo que importa no es su severidad sino cuánto tarda en llegar desde el intento, porque la que llega días después llega sola y no se engancha con nada. Luego se pone en fila el intento y su consecuencia, recordando que el orden decide el signo del cambio y que ver el modelo antes de intentar deja al que aprende reconociendo en vez de produciendo. Y al final se cambia UNA sola cosa, la más barata, casi siempre la misma: convertir un rato de recepción en un rato de producción con comprobación inmediata, y volver a medir a la semana, porque una decisión sin segunda medición es una opinión con fecha.';

const critCompareBank=[{"a":"Contestar y comprobar en el mismo minuto.","b":"Contestar y recibir la corrección el lunes siguiente.","ga":"Caso A: el intento y su consecuencia quedan encadenados, que es el orden que la regla premia, y el alumno todavía sabe por qué contestó eso.","gb":"Caso B: la corrección llega sola, sin nada a lo que engancharse, y el error ha tenido ocho días para hacerse camino."},{"a":"Intentar el pasaje y después oír la grabación.","b":"Oír la grabación veinte veces y después intentar el pasaje.","ga":"Caso A: la grabación corrige un intento concreto, así que hay algo que participa en encender algo. Primero las manos, después el modelo.","gb":"Caso B: se practica escuchar, que es una destreza real y no es la que se examina. Se llega al instrumento con el oído lleno y las manos vacías."},{"a":"Preguntar los pares de la tabla sueltos y al azar.","b":"Cantar la tabla entera de corrido, veinte veces.","ga":"Caso A: se practica lo que después se va a pedir, así que cada par queda accesible por su propia puerta.","gb":"Caso B: se refuerza una cadena en un solo orden, y para llegar a un eslabón hay que arrancar desde el primero."},{"a":"Veinte minutos produciendo y comprobando.","b":"Dos horas con el material puesto de fondo.","ga":"Caso A: pocos minutos, pero cada intento cumple las cuatro piezas del postulado: cercanía, participación, repetición y dirección.","gb":"Caso B: muchas horas de coincidencia perfecta y causalidad cero. Cumple el eslogan y no cumple el postulado."}];

const critCauseBank=[{"cause":"Se estudia con el material puesto de fondo y sin producir nada.","guide":"Se acumulan horas de coincidencia, la sensación de haber avanzado sube, y al llegar el momento de producir no hay nada cableado: la conclusión falsa que queda apuntada es que uno no sirve para eso."},{"cause":"La corrección llega días después del intento.","guide":"El error se repite intacto durante esos días, se hace camino, y cuando la corrección llega ya no corrige un intento sino una costumbre, que es una obra mucho más cara."},{"cause":"Se repite mucho y nadie nombra el fallo.","guide":"La regla multiplica lo que encuentra, así que se cablea el error con el mismo cuidado que el acierto, y quien practica se vuelve rápido y seguro haciéndolo mal."},{"cause":"Se cita el eslogan de 1992 como si fuera el postulado de 1949.","guide":"El maestro que lo cree pone dos cosas juntas y espera, en vez de hacer producir y corregir, y una atribución falsa en la portada le quita autoridad a todo lo demás que diga esa guía."},{"cause":"Se compra entrenamiento genérico en vez de practicar la tarea real.","guide":"Se mejora en el juego comprado y en nada más, porque el cambio es específico, y encima el dinero y las horas gastadas dejan de estar disponibles para lo que sí transfería."},{"cause":"Se ve el modelo antes de intentar.","guide":"Se practica reconocer el procedimiento, la sensación de dominio sube muchísimo, y el día que hay que producirlo aparece el hueco entero, que es el orden más caro posible para descubrirlo."}];
const critEffectBank=[{"effect":"Angelly empezó a pedir cosas en inglés sin pensarlo.","guide":"Se cambiaron veinte minutos de video de fondo por veinte minutos de repetir en voz alta y contestar, con comprobación inmediata. Las horas bajaron y lo cableado subió."},{"effect":"En esa aula el mismo error dejó de repetirse cada semana.","guide":"La maestra cambió corregir mucho por corregir pronto: cinco preguntas comprobadas en el momento, dentro de la clase, en vez de veinte devueltas el lunes."},{"effect":"Jael contesta siete por ocho sin cantar la tabla.","guide":"Se practicaron los pares sueltos y al azar, que es como llegan en la vida, con la respuesta comprobada enseguida. Se practicó lo que se iba a pedir."},{"effect":"El papá escribe con diez dedos y ya no mira el teclado.","guide":"Aceptó escribir más lento durante tres semanas, que es lo que cuesta que quepa la corrección, y practicó con un programa que le decía el fallo en la misma tecla."},{"effect":"La guía de maestro de M.E.T.A.S cita bien la regla.","guide":"Se puso el postulado con su fuente y su año, y el eslogan quedó dentro, como ejemplo de cita mal atribuida, que es el uso honesto que le quedaba."},{"effect":"La familia decidió lo de la academia sin pelearse.","guide":"Fueron a mirar una clase y apuntaron dos números: minutos que habla cada alumno y veces que lo corrigen por hora. Con esos dos datos la discusión se acabó sola."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 La práctica sobre la mesa · Forma ${cf} · La regla de Hebb, bien contada · Ruta del Barro Vivo`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La práctica sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué produce quien practica y qué solo recibe, quién corrige y cuánto tarda, y en qué orden quedan el intento y su consecuencia? Explica qué quedará cableado en un mes y qué UNA cosa cambiarías.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos cumple el postulado y no solo el eslogan? 2. ¿Por qué no cablean lo mismo?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La práctica sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La práctica sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué produce quien practica y qué solo recibe, quién corrige y cuánto tarda, y en qué orden quedan el intento y su consecuencia? Explica qué quedará cableado en un mes y qué UNA cosa cambiarías.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos cumple el postulado y no solo el eslogan? 2. ¿Por qué no cablean lo mismo?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La práctica sobre la mesa La regla de Hebb, bien contada · Ruta del Barro Vivo · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La práctica sobre la mesa · La regla de Hebb, bien contada · Ruta del Barro Vivo · Etapa 1 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La práctica sobre la mesa · La regla de Hebb, bien contada · Ruta del Barro Vivo · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🎯","label":"La tarea","text":"Se elige <strong>qué se va a producir</strong>, no qué se va a mirar. Tiene que parecerse a lo que después se va a pedir. <strong>Se cae:</strong> eligiendo material («voy a ver este curso») en vez de conducta («voy a decir diez frases»)."},{"y":"2","icon":"🐢","label":"La velocidad","text":"Se baja hasta que <strong>quepa la corrección</strong>. Un error alcanzado en el primer intento vuelve al corral; alcanzado a la décima ya es costumbre. <strong>Se cae:</strong> con la prisa, que es la enemiga natural de esta regla."},{"y":"3","icon":"✍️","label":"El intento","text":"Se <strong>produce sin mirar el modelo</strong>: se dice, se escribe, se toca, se resuelve. Aquí es donde A empieza a participar en algo, y sin este momento no hay nada que la regla pueda premiar."},{"y":"4","icon":"🔎","label":"La comprobación","text":"Enseguida, en el <strong>mismo minuto</strong>: la respuesta tapada, la grabación, el resultado visible, la persona que mira. <strong>Se cae:</strong> dejándola para el final de la sesión, que ya es tarde, o para el lunes, que es tardísimo."},{"y":"5","icon":"🗣️","label":"El nombre del fallo","text":"Se dice <strong>en voz alta qué salió mal</strong> antes del intento siguiente. Nombrarlo es lo que impide que el intento que viene nazca de la gana de acabar en vez de nacer de lo que vio el ojo."},{"y":"6","icon":"🔁","label":"La repetición dirigida","text":"Ahora sí se repite, pero <strong>con la corrección puesta</strong>. La repetición no es un mérito: es un multiplicador, y solo conviene multiplicar después de haber arreglado lo que se va a multiplicar."},{"y":"7","icon":"📊","label":"El recuento","text":"Se apunta <strong>cuántos intentos y cuántas correcciones</strong> hubo, no cuántos minutos. <strong>La meta:</strong> que el número de intentos suba y la sesión siga cabiendo en la tarde. Es el registro que esta ruta va llenando."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(pregunto){sfx(pregunto?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(pregunto){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🎯</span><span class="ms-text"><strong>Preguntaste pares sueltos y al azar:</strong> siete por ocho, siete por cuatro, siete por nueve. Angelly falló seis de veinte, y cada fallo se corrigió en el mismo segundo, antes de la pregunta siguiente.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🏺</span><span class="ms-text"><strong>Se practicó lo que después se pide:</strong> cada par quedó con su propia puerta de entrada, porque el intento participó en el resultado. A la semana contesta suelto y sin cantar.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🔁</span><span class="ms-text"><strong>La cantó veinte veces más:</strong> las veinte le salieron perfectas, porque cantada nunca falla. La sensación de dominio subió, y con razón: hizo muy bien lo que hizo.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⏱️</span><span class="ms-text"><strong>Se reforzó la cadena, no el par:</strong> veinte repeticiones más de un solo orden. En la fila del mercado sigue tardando cinco segundos, porque para llegar al eslabón hay que arrancar desde el primero.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"postulado":{"nombre":"El postulado de 1949","icon":"📕","estructura":{"title":"Qué es","info":"• El enunciado de <strong>Donald Hebb</strong>, capítulo 4 de «The Organization of Behavior»<br>• Si A <strong>participa repetidamente en hacer disparar</strong> a B, crece la eficacia de A hacia B<br>• Cuatro piezas: cercanía, participación, repetición y dirección"},"funcion":{"title":"Cómo se reconoce","info":"• Trae un <strong>verbo de causa</strong>: participar, tomar parte, contribuir<br>• Trae una <strong>dirección</strong>: de A hacia B, no al revés<br>• Y se declara <strong>postulado</strong>, no ley: era una conjetura por comprobar"},"enfermedades":{"title":"Dónde se cae","info":"• Citándolo por el eslogan, que le quita la participación<br>• Presentándolo como <strong>hecho demostrado en 1949</strong>, que no lo era<br>• Olvidando que la idea general venía de antes (Tanzi, Ramón y Cajal)"},"cuidados":{"title":"En esta casa","info":"• Se cita <strong>entero y con su año</strong>, o no se cita<br>• Se dice que era conjetura, y qué vino después a medirlo<br>• Y se traduce a conducta: <strong>producir, fallar, corregir enseguida</strong>"}},"orden":{"nombre":"El orden de disparo","icon":"⏱️","estructura":{"title":"Qué es","info":"• La <strong>plasticidad dependiente del orden de disparo</strong><br>• A antes que B: la conexión <strong>se refuerza</strong><br>• A después que B: la misma conexión <strong>se debilita</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se mide en <strong>decenas de milisegundos</strong>: Bi y Poo (1998)<br>• Markram y colegas lo publicaron en <strong>Science, 1997</strong><br>• Mismo par de células, mismo número de repeticiones, resultado contrario"},"enfermedades":{"title":"Dónde se cae","info":"• Creyendo que invertir el orden deja las cosas <strong>igual</strong><br>• Citándolo como probado en la vida diaria: se midió en <strong>tejido y cultivo</strong><br>• Confundiendo la ventana con el periodo crítico, que es otra cosa (etapa 3)"},"cuidados":{"title":"En esta casa","info":"• Primero el intento, <strong>después</strong> la comprobación<br>• La corrección vale por su <strong>cercanía</strong>, no por su severidad<br>• Y ver el modelo antes de intentar se considera invertir el orden"}},"eslogan":{"nombre":"El eslogan de 1992","icon":"📣","estructura":{"title":"Qué es","info":"• «Lo que dispara junto se cablea junto»<br>• Formulación de <strong>Löwel y Singer</strong>, en Science, en 1992<br>• La rima que corrió el mundo es de <strong>Carla Shatz</strong>, ese mismo año"},"funcion":{"title":"Cómo se reconoce","info":"• Aparece <strong>firmado por Hebb</strong> en anuncios y en cursos<br>• No nombra ninguna dirección ni ningún orden<br>• Su virtud es que se pega; su defecto es <strong>lo que borra al pegarse</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Dando por bueno que basta con <strong>poner las cosas juntas</strong><br>• Vendiendo exposición pasiva como si fuera práctica<br>• Repitiendo la atribución falsa hasta en guías de maestro"},"cuidados":{"title":"En esta casa","info":"• Se usa <strong>solo como ejemplo de cita mal atribuida</strong><br>• Y al lado va siempre el postulado entero, con su año<br>• Los dos estudios que lo originan se citan con su etiqueta"}},"practica":{"nombre":"La práctica activa","icon":"🎯","estructura":{"title":"Qué es","info":"• <strong>Producir</strong> la respuesta, ver el resultado y <strong>corregir enseguida</strong><br>• Es la traducción a conducta de las cuatro piezas del postulado<br>• Ericsson y colegas (1993) la llamaron práctica deliberada"},"funcion":{"title":"Cómo se reconoce","info":"• Se cuenta en <strong>intentos y correcciones</strong>, no en minutos<br>• Algo sale de las manos o de la boca de quien practica<br>• Y la comprobación llega <strong>en el mismo minuto</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Cambiándola por exposición, que se siente igual de productiva y cuesta menos<br>• Corrigiendo <strong>mucho y tarde</strong> en vez de poco y pronto<br>• Prometiendo con ella lo que la <strong>especificidad</strong> niega (Macnamara y colegas, 2014)"},"cuidados":{"title":"En esta casa","info":"• Ninguna práctica se da por buena si <strong>no produce y no corrige</strong><br>• Se practica lo que después se va a pedir, y en desorden<br>• Y se apunta el recuento, que es lo que la ruta va llenando"}}};
let labParte='postulado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
