// ===================== LECTURAS (normas 5, 5-quater y 5-quinquies) =====================
// Cinco textos (Borges, Cervantes, Harari, la entrevista de la casa y la
// conversación Quintero-Gala) con tres baterías: comprensión (25, cinco por
// voz), completar (10) y análisis complejo (10, sin XP a propósito). El motor
// es el de la referencia del escocés dorado, con los colores y el pie de esta
// misión. Las preguntas se contestan con los textos delante: son examen de
// lectura, no de memoria, que es exactamente la lección de la etapa.
const lectComprensionBank=[{"t":"Borges","q":"¿Qué prohibía don Aciar a sus alumnos?","o":["a) Estudiar más de una hora seguida","b) Tocar delante de otros alumnos","c) Aprender piezas que no fueran de su gusto","d) Repetir un pasaje sin haber nombrado el error en el instante en que ocurría"],"c":3},{"t":"Borges","q":"¿Para qué usaba don Aciar el metrónomo alemán?","o":["a) Para medir cuánto duraba la clase","b) Para castigar al que iba desacompasado","c) Para ir tan despacio que la corrección alcanzara a llegar","d) Para que los alumnos tocaran cada vez más rápido"],"c":2},{"t":"Borges","q":"Cuando un alumno decía que había repetido cien veces, ¿qué contestaba el maestro?","o":["a) Que estaba muy bien y que repitiera doscientas","b) Que la guitarra no era para él","c) «Cien veces qué», porque la repetición multiplica lo que encuentra","d) Que buscara otro maestro más rápido"],"c":2},{"t":"Borges","q":"¿Qué regla tenía don Aciar sobre escuchar la grabación de la pieza?","o":["a) Que se oyera veinte veces antes de tocar","b) Que no se oyera antes de intentar el pasaje: primero las manos, después el modelo","c) Que no se oyera nunca","d) Que se oyera solo en clase"],"c":1},{"t":"Borges","q":"¿Qué encontró el narrador, años después, entre dos estantes de una biblioteca?","o":["a) El libro de Hebb de 1949 con el postulado que explicaba la pedagogía del viejo","b) Una partitura anotada por don Aciar","c) Un tratado de acústica del siglo XIX","d) Las cartas del maestro a sus alumnos"],"c":0},{"t":"Cervantes","q":"¿Qué quería conseguir el mozo que llegó a la fragua?","o":["a) Sacar el oficio de herrero en tres días","b) Comprar un caballo","c) Casarse con la hija del ventero","d) Aprender a leer y escribir"],"c":0},{"t":"Cervantes","q":"¿Qué le respondió el maestro Cebrián cuando el mozo dijo que llevaba dos años viendo herrar?","o":["a) Que él había visto llover cuarenta años y no por eso hacía llover","b) Que entonces ya era oficial","c) Que dos años eran pocos y que hacían falta diez","d) Que se fuera a otra fragua"],"c":0},{"t":"Cervantes","q":"¿Cómo quedó el hierro después de los treinta primeros golpes del mozo?","o":["a) Perfectamente derecho","b) Partido en dos","c) Igual que al principio","d) Torcido como cuerno de cabra"],"c":3},{"t":"Cervantes","q":"¿En qué consistía la doctrina del herrero viejo?","o":["a) Dar los golpes lo más fuerte posible","b) Contar los golpes hasta cien sin parar","c) Un golpe y mirar, decir en voz alta lo que salió, y que el golpe siguiente nazca de lo que dijo el ojo","d) Copiar exactamente lo que hace el maestro"],"c":2},{"t":"Cervantes","q":"¿Qué hizo escribir Cebrián con carbón en la pared de la fragua, en vez de cobrar?","o":["a) El precio de las herraduras","b) Que allí no se repite lo que no se ha mirado, porque el hierro aprende igual el yerro que el acierto","c) Los nombres de sus aprendices","d) Una oración a los santos del oficio"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿qué compró la evolución al alargar tanto la infancia humana?","o":["a) Un cuerpo más resistente","b) Una vida más larga","c) Una dentadura más fuerte","d) Un cerebro que se termina de fabricar por fuera, con lo que le pasa"],"c":3},{"t":"Harari","q":"¿Cómo se enseñaba la escritura cuneiforme en Mesopotamia, según el ensayo?","o":["a) Copiando tablillas y recibiendo la corrección en el mismo barro húmedo","b) Escuchando recitar al escriba mayor","c) Memorizando listas de signos sin escribirlos","d) Solo a los hijos de los reyes"],"c":0},{"t":"Harari","q":"¿Qué dice el ensayo sobre la regla de las diez mil horas?","o":["a) Que está confirmada por la neurociencia","b) Que la escribió Hebb en 1949","c) Que se midió en los taxistas de Londres","d) Que viene de un libro de divulgación de 2008 y no de la ciencia, y que Ericsson la desmintió"],"c":3},{"t":"Harari","q":"¿Qué encontró el equipo de Eleanor Maguire en 2000 con los taxistas de Londres?","o":["a) Un cerebro más grande en general","b) Más grande la parte del hipocampo que maneja mapas, y no un cerebro mejor en todo","c) Que conducir encoge el cerebro","d) Que no había ninguna diferencia"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿qué tienen en común un aprendiz de herrero y una red neuronal artificial?","o":["a) Que los dos producen una respuesta, la comparan con lo esperado y ajustan según el error","b) Que los dos aprenden mirando","c) Que ninguno de los dos necesita corrección","d) Que los dos trabajan con metales"],"c":0},{"t":"Entrevista","q":"¿Qué quería ser Donald Hebb antes de dedicarse a la ciencia?","o":["a) Médico, como sus padres","b) Maestro de escuela toda la vida","c) Novelista","d) Pescador en Nueva Escocia"],"c":2},{"t":"Entrevista","q":"¿Por qué dice Hebb que usó la palabra «postulado» y no «ley»?","o":["a) Porque se lo pidió su editor","b) Porque significa que lo da por supuesto para seguir razonando y alguien tendrá que comprobarlo","c) Porque no le gustaba la palabra ley","d) Porque ya había una ley con ese nombre"],"c":1},{"t":"Entrevista","q":"¿En qué palabra del postulado se detiene Soler Serrano, y por qué?","o":["a) En «axón», porque es la parte física","b) En «repetida», porque es lo que más se olvida","c) En «metabólico», porque es el término técnico","d) En «participa», porque no es lo mismo que coincidir e implica causa y orden"],"c":3},{"t":"Entrevista","q":"¿Qué le preocupa a Hebb del eslogan, más que la autoría?","o":["a) Que no rime bien en inglés","b) Que se cobre dinero por él","c) Lo que la frase hace cuando llega: el maestro que solo pone cosas juntas y espera","d) Que Löwel y Singer no lo citaran"],"c":2},{"t":"Entrevista","q":"Sobre las ratas que se llevó a casa en 1947, ¿cuál dice Hebb que fue la diferencia?","o":["a) Que comieron mejor","b) No el estímulo, sino quién producía el movimiento","c) Que eran ratas más jóvenes","d) Que hacía más calor en la casa"],"c":1},{"t":"Quintero y Gala","q":"¿Qué responde Gala a la pregunta de si es lo que quiso ser o lo que repitió?","o":["a) Que es exactamente lo que quiso ser","b) Que no lo sabe y prefiere no pensarlo","c) Que es lo que repitió, y que lo que quiso ser está en un cajón","d) Que es lo que otros quisieron que fuera"],"c":2},{"t":"Quintero y Gala","q":"¿Qué ejemplo del teatro usa Gala para explicar la diferencia entre acompañar y aprender?","o":["a) El estreno de una obra en Madrid","b) Los ensayos de «Anillos para una dama», donde la función empieza la noche en que el actor suelta el papel","c) Una gira por provincias","d) La lectura de un guion en una radio"],"c":1},{"t":"Quintero y Gala","q":"¿Con qué imagen explica Gala la costumbre?","o":["a) Con un reloj de arena","b) Con una vela que se consume","c) Con el camino que dibujan los pies en la alameda y al que ya no se le discute","d) Con un espejo empañado"],"c":2},{"t":"Quintero y Gala","q":"¿Qué les pide Gala el primer día a los jóvenes de su Fundación de Córdoba?","o":["a) Que no le traigan lo que han leído sino lo que han escrito, y pronto, para que sea malo delante de él","b) Que lean a los clásicos durante un año","c) Que aprendan de memoria un poema diario","d) Que no escriban hasta estar seguros"],"c":0},{"t":"Quintero y Gala","q":"¿Cuál es la frase con que Gala cierra la conversación?","o":["a) Que el talento se lleva en la sangre","b) Que no confundan asistir con hacer, porque uno se vuelve lo que repite y nada más","c) Que hay que escribir todos los días a la misma hora","d) Que la juventud se desperdicia en los jóvenes"],"c":1},{"t":"Debate","q":"Según el careo, ¿cuál es exactamente la pregunta en disputa?","o":["a) Si la regla de Hebb existe o es un invento","b) Quién escribió antes el postulado","c) Si el receptor NMDA existe","d) Si la regla de Hebb es el mecanismo del aprendizaje o solo una pieza de un mecanismo mayor"],"c":3},{"t":"Debate","q":"¿Qué mostraron Bliss y Lømo en 1973, según la defensa?","o":["a) Que estimular una vía del hipocampo la dejaba potenciada durante horas","b) Que las neuronas mueren sin estímulo","c) Que el magnesio tapa el receptor NMDA","d) Que la dopamina señala el error de predicción"],"c":0},{"t":"Debate","q":"La objeción dice que una regla puramente hebbiana, dejada sola, no puede funcionar. ¿Por qué?","o":["a) Porque es demasiado lenta","b) Porque nadie ha logrado medirla","c) Porque solo funciona en animales jóvenes","d) Porque es una realimentación positiva sin freno: se refuerza a sí misma hasta saturarse"],"c":3},{"t":"Debate","q":"¿Qué aporta el llamado tercer factor, según la objeción?","o":["a) Un segundo detector de coincidencias","b) Una señal que dice qué merece la pena aprenderse, porque la coincidencia sola no lo dice","c) Una manera de medir milisegundos","d) Una copia de seguridad de la sinapsis"],"c":1},{"t":"Debate","q":"Según el cierre del careo, ¿qué dato resolvería la disputa?","o":["a) Medir el cambio de sinapsis concretas en un animal despierto que aprende algo suyo, con sus patrones naturales","b) Repetir el experimento de 1973 con más conejos","c) Preguntar a más investigadores","d) Aumentar la potencia de los estímulos en cultivo"],"c":0}];
const lectCompletarBank=[{"t":"Borges","q":"La nota de tres palabras que dejó don Aciar con el metrónomo decía «despacio, para ___».","a":"corregir"},{"t":"Borges","q":"El narrador cuenta que Bi y Poo midieron el orden de disparo en el año ___.","a":"1998"},{"t":"Cervantes","q":"Al final de la tarde, al mozo le salieron cuatro golpes derechos de ___.","a":"doce"},{"t":"Cervantes","q":"El maestro herrero de la fragua se llamaba ___.","a":"Cebrián"},{"t":"Harari","q":"Frank Rosenblatt construyó el perceptrón en el año ___.","a":"1958"},{"t":"Harari","q":"Macnamara, Hambrick y Oswald dejaron el efecto de la práctica en torno al ___ por ciento de la variación.","a":"doce"},{"t":"Entrevista","q":"Joaquín Soler Serrano dirigió y presentó en TVE el programa de entrevistas ___.","a":"A fondo"},{"t":"Entrevista","q":"Hebb presidió en 1960 la Asociación Estadounidense de ___.","a":"Psicología"},{"t":"Quintero y Gala","q":"El perro de Antonio Gala, que le sacó un libro entero de conversaciones, se llamaba ___.","a":"Troylo"},{"t":"Quintero y Gala","q":"Quintero le cuenta a Gala que Hebb escribió su postulado en un libro del año ___.","a":"1949"},{"t":"Debate","q":"En 1984, Nowak y sus colegas mostraron que el receptor NMDA está tapado por un ion de ___.","a":"magnesio"},{"t":"Debate","q":"Turrigiano y sus colegas mostraron en 1998 que una neurona ___ todas sus sinapsis a la vez, conservando las proporciones.","a":"reescala"}];
const lectAnalisisBank=[{"t":"Borges","q":"Don Aciar prohibía repetir y contestaba «cien veces qué». Explica su método completo y por qué el narrador tardó cuarenta años en entenderlo.","guia":"El método tiene tres reglas y las tres salen del postulado sin que el viejo lo supiera. Primero, no dejaba repetir un pasaje si no se sabía de antemano qué iba a salir mal, y no dejaba pasar de compás si el error no se nombraba en voz alta en el instante en que ocurría: la corrección tiene que caber dentro de la ventana, y por eso ponía el metrónomo tan lento. Segundo, trataba la repetición como un multiplicador y no como un mérito, y de ahí la respuesta «cien veces qué»: si lo que se multiplica es el pulgar torcido, cien repeticiones producen un error firmemente cableado. Tercero, no permitía oír la grabación antes de intentar el pasaje, porque el orden decide: primero las manos, después el modelo. El narrador tardó cuarenta años porque el método se siente lento y feo, y porque la lentitud se confunde con torpeza mientras no se mide el resultado a los diez años, que es cuando los alumnos de los otros maestros ya no tocaban."},{"t":"Borges","q":"El cuento dice que la frase que se pegó a la memoria de la especie es justo la que borra la condición para pegarse a la memoria. Explica esa ironía.","guia":"La frase famosa es «lo que dispara junto se cablea junto», que rima, es corta y por eso viaja. Lo que borra es la palabra que el postulado de 1949 exige: participar. En el original, A tiene que tomar parte en hacer disparar a B, y de ahí salen una causa y un orden; en el eslogan basta con la simultaneidad, que no es lo mismo y que no cablea nada. La ironía es doble. Primero, porque una frase que triunfa por ser fácil de recordar enseña precisamente que basta con poner cosas juntas, que es lo contrario de lo que hace falta para recordar. Y segundo, porque el propio eslogan es un caso de lo que niega: se pegó por repetición y por compañía (aparece siempre al lado del nombre de Hebb) y no porque nadie comprobara nada, que es exactamente la manera de aprender que el postulado no premia."},{"t":"Cervantes","q":"El mozo dio sesenta golpes por la mañana y doce por la tarde, y por la tarde le salieron cuatro derechos. Explica qué cambió, con el vocabulario de la etapa.","guia":"No cambió la cantidad de esfuerzo, que bajó, ni la fuerza del brazo, que era la misma: cambió que entre golpe y golpe hubo una comprobación y un nombre para el fallo. Por la mañana hubo sesenta repeticiones y cero correcciones, así que se cumplió el postulado al pie de la letra y quedó reforzada la manera de torcer el hierro, que es lo que se practicó. Por la tarde cada golpe se miró, se dijo en voz alta qué había salido, y el golpe siguiente nació de lo que vio el ojo y no de la gana de acabar: eso encadena el intento con su consecuencia, en el orden que la regla premia y dentro de un tiempo en que todavía se enganchan. Es la misma cuenta que la de don Neto en el guion y la del papá de los dos dedos: menos intentos mejor puestos ganan a muchos intentos a ciegas."},{"t":"Cervantes","q":"Cebrián no cobró la doctrina: la hizo escribir con carbón en la pared. Explica qué dice esa frase y por qué en la pared y no en un papel.","guia":"La frase dice que allí no se repite lo que no se ha mirado, porque el hierro no sabe de intenciones y aprende igual el yerro que el acierto, y con la misma paciencia. Es el postulado dicho por un herrero: la regla no distingue entre lo bueno y lo malo, refuerza lo que se repite, y por eso la corrección no es un adorno pedagógico sino la única manera de elegir qué se va a reforzar. Que sea en la pared y no en un papel tiene dos lecturas y las dos valen. La práctica: el papel se pierde y la pared espera a los que vengan, así que la doctrina queda donde se trabaja y no donde se guarda. Y la del propio capítulo, que el padre del mozo dice en voz alta: a los veinte años nadie lee esa doctrina si se la dan escrita, así que hay que ponerla donde la vea todos los días quien todavía no está listo para buscarla."},{"t":"Harari","q":"El ensayo dice que las pantallas ofrecen «coincidencia perfecta y causalidad cero». Explica la frase y aplícala a un caso concreto de tu casa.","guia":"Un video, un audio o una clase grabada avanzan solos: los estímulos ocurren a la vez que la tarde, pero nada de lo que hace quien mira participa en lo que ocurre en la pantalla. Eso cumple el eslogan al pie de la letra, porque todo dispara junto, y no cumple ninguna de las cuatro piezas del postulado, porque falta la participación y con ella se van la dirección y el orden. El caso de la casa es el de las sesenta horas de video de inglés en un mes mientras se ordena el cuarto: la sensación de aprovechar el tiempo es alta y lo cableado es la costumbre de tener ruido en inglés de fondo. La corrección no es dejar la pantalla, sino cambiar veinte minutos de recepción por veinte de producción con comprobación inmediata. Se valora que el caso sea real y que se cuente en veces producidas, no en minutos."},{"t":"Harari","q":"El ensayo cita a Ericsson (1993) y a Macnamara y colegas (2014) uno detrás del otro. Explica por qué la casa no cita al primero sin el segundo.","guia":"Porque Ericsson describió la práctica deliberada, trabajar al borde de la propia capacidad con retroalimentación inmediata, y esa descripción es sólida y sigue siendo el mejor método de entrenamiento conocido, pero el tamaño de su efecto se infló muchísimo por el camino. Macnamara, Hambrick y Oswald revisaron el conjunto de la evidencia en 2014 y encontraron que la práctica explica alrededor del doce por ciento de la variación entre personas, menos en educación y en profesiones. Citar solo a Ericsson deja la promesa de que cualquiera llega a cualquier sitio con horas suficientes, que es la versión de las diez mil horas que popularizó un libro de divulgación de 2008 y que el propio Ericsson desmintió. Citar solo a Macnamara deja la conclusión contraria y también falsa, que practicar da igual. La regla de la casa es que ninguna afirmación entra al mapa sin su mejor crítica en la casilla de al lado."},{"t":"Entrevista","q":"Hebb insiste en que llamó «postulado» a su enunciado y en que la idea general no era suya. ¿Por qué importan esas dos precisiones para la regla del estatus?","guia":"Porque las dos son declaraciones de estatus hechas por el propio autor, y la regla de la casa dice que ningún estudio entra sin su etiqueta. Llamarlo postulado significa: esto es una conjetura teórica, no un resultado experimental, y alguien tendrá que comprobarlo. Quien lo cita como ley demostrada de 1949 está inflando la fuente, aunque lo haga con admiración. Decir que la idea general venía de antes, porque en el siglo XIX Tanzi y el propio Ramón y Cajal habían conjeturado que el uso fortalece las conexiones, evita el otro inflado, el del genio solitario, y sitúa su aportación en lo concreto: la condición de participación, la asamblea de células y la secuencia de fases. Y tiene una consecuencia práctica: como era conjetura, lo que la sostiene hoy son las mediciones de 1997 y 1998, que a su vez traen su propia letra chica."},{"t":"Entrevista","q":"Sobre las ratas de 1947, Hebb dice que la diferencia no fue el estímulo sino quién producía el movimiento. Explica esa frase y qué tiene que ver con el verbo «participa».","guia":"Las ratas que se quedaron en la jaula tenían delante exactamente el mismo laboratorio que las que se fueron a la casa de Hebb: los mismos ruidos, las mismas luces, el mismo mundo al otro lado de los barrotes. Lo que no tenían era la posibilidad de tropezar con él, subir una escalera, caerse y volver a subir. Por eso Hebb dice que la diferencia no fue el estímulo. Y ahí está el verbo del postulado hecho biografía de rata: participar no es estar presente, es que algo de lo que uno hace tome parte en lo que ocurre después. La misma frase explica al nieto que mira quince años el torno del abuelo, al actor que ensaya con el papel en la mano y al alumno con el video de fondo. Se valora que la respuesta conecte las tres cosas: la anécdota, el verbo y algún caso propio."},{"t":"Quintero y Gala","q":"Gala dice que la costumbre es «un escultor lento» y cuenta el camino de la alameda. Explica qué parte del postulado está diciendo con esa imagen.","guia":"El camino de la alameda no lo dibujó ningún ingeniero: lo dibujaron los pies pasando por donde era más cómodo, y al año había un surco al que ya no se le discute. Eso es la repetición como multiplicador: nadie decidió aquel camino y todos lo obedecían después. La parte del postulado que dice la imagen es la que más incomoda, y Gala la dice entera: el escultor no distingue, talla con la misma paciencia la virtud y el vicio, la buena caligrafía y la mala, el pulgar torcido del alfarero y el derecho. Es decir, la regla refuerza lo que se repite y no lo que conviene, y por eso practicar sin corrección es la manera más segura de volverse muy bueno en algo que se hace mal. Se valora que la respuesta note lo que la imagen añade a la definición técnica: que el trabajo del escultor ocurre mientras uno mira para otro lado."},{"t":"Quintero y Gala","q":"«Que no confundan asistir con hacer.» Explica por qué Gala llama a eso la confusión de nuestro tiempo y la más cara.","guia":"Asistir es estar delante: leer a los maestros, ver el ensayo, oír la conferencia, tener el tutorial puesto. Hacer es producir algo que salga de uno y pueda salir mal delante de alguien. Gala lo llama la confusión de nuestro tiempo porque nunca fue tan fácil asistir a todo y tan raro producir algo, y la llama la más cara por lo que él mismo cuenta de su Fundación: el joven que lee tres años siente que avanza, y el que escribe siente que no puede, así que la sensación va justo al revés que el provecho y empuja a cada uno hacia lo que menos rinde. En el vocabulario de la etapa: asistir es coincidencia y hacer es participación, y solo la segunda cumple el postulado. Se valora que la respuesta enlace la trampa de la sensación con la cláusula de especificidad: uno no se vuelve lo que admira, se vuelve lo que repite, y exactamente eso."},{"t":"Debate","q":"Resume las dos posturas del careo en su mejor versión, y di qué le concede cada una a la otra.","guia":"La defensa sostiene que la regla es el mecanismo del aprendizaje, y no lo dice de palabra: se apoya en la potenciación a largo plazo de Bliss y Lømo (1973), en el receptor NMDA como detector de coincidencias con su bloqueo por magnesio (Nowak y colegas, 1984), en el experimento de Morris y colegas (1986) donde bloquear ese receptor tumba el aprendizaje espacial sin tocar el nado, y en la medición del reloj por Markram (1997) y Bi y Poo (1998). La objeción sostiene que la regla no basta, y da tres razones: sola es una realimentación positiva que se satura, y por eso hizo falta el umbral móvil de Bienenstock, Cooper y Munro (1982) y el reescalado sináptico de Turrigiano y colegas (1998); la coincidencia dice qué va con qué pero no qué merece aprenderse, y por eso hacen falta reglas de tres factores con la dopamina señalando el error de predicción (Schultz, Dayan y Montague, 1997); y la ventana está medida sobre todo en rodajas y cultivos, con la crítica explícita de Lisman y Spruston (2005) y la revisión de Feldman (2012). Las concesiones son lo que se valora: la objeción concede que la potenciación existe, que el NMDA detecta coincidencias y que el orden cambia el signo; la defensa concede que hacen falta mecanismos estabilizadores y un tercer factor, y sostiene que completan la regla en vez de sustituirla."},{"t":"Debate","q":"El careo termina diciendo qué dato resolvería la disputa. Explica cuál es, por qué las dos partes lo aceptarían, y qué gana quien estudia aunque no se resuelva nunca.","guia":"El dato sería medir el cambio de sinapsis concretas en un animal despierto que está aprendiendo algo suyo, con sus patrones de disparo naturales y sin estímulos escogidos por el laboratorio, y comprobar si el signo del cambio se predice con el orden y la ventana. Las dos partes lo aceptarían porque ataca justo el punto que las separa y no otro: nadie discute lo que pasa en una rodaja de tejido, se discute cuánto de eso opera en la vida del animal, así que el experimento decisivo tiene que ocurrir en la vida del animal. Y lo que gana quien estudia sin esperar el resultado es lo que el propio careo pone en el terreno común: los dos lados exigen que el alumno produzca y que la consecuencia llegue pegada al intento, porque la actividad coincidente y dirigida cambia las conexiones y la mera compañía no. Se valora especialmente que la respuesta note que ninguno de los dos bandos defiende el eslogan de 1992, que es lo que casi todo el mundo cita."}];
/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con las dos
// entrevistas la etiqueta crece: además del pastiche hay que declarar que el
// encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={
  borges:{titulo:'El metrónomo de don Aciar',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'Donde se cuenta lo que sucedió en la fragua a un mozo que quería aprender el oficio en tres días, y de la doctrina que le dio un herrero viejo sobre el orden con que se aprende',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'La especie que se cablea a sí misma',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'El hombre que escribió una conjetura y le salió una industria',tipo:'Entrevista imaginada con Donald O. Hebb, a la manera de Joaquín Soler Serrano',ficcion:true},
  gala:{titulo:'La costumbre, que es un escultor lento',tipo:'El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)',ficcion:true},
  debate:{titulo:'¿Basta la regla de Hebb?',tipo:'Careo: las dos posturas de una disputa abierta, con sus réplicas',careo:true},
};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Los investigadores se citan en tercera persona como fuentes, <strong>toda obra, revista, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · La regla de Hebb, bien contada · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#431407;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#9a3412;border-bottom:1.5pt solid #9a3412;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #9a3412;background:#fff7ed;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#431407;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#9a3412;background:#fff7ed;border-left:3pt solid #9a3412;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#9a3412;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🏺 La regla de Hebb, bien contada${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🏺 Ruta del Barro Vivo · Etapa 1 de 6</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaImpresa(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  const _ap=window.FaroLecturas;
  const preg=(_ap&&_ap.preguntasImpresas)?_ap.preguntasImpresas(clave):'';
  const _cuerpo=(_ap&&_ap.etiquetaCareo)?_ap.etiquetaCareo(clave,cuerpo):cuerpo;
  _abreImpresion(_hojaImpresa(meta.titulo,_cuerpo+preg+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🏺 Ruta del Barro Vivo · Etapa 1 de 6</span><span>Las seis lecturas 📖</span></div>`
    +`<h1>Las seis lecturas de «La regla de Hebb, bien contada»</h1><div class="tipo">Un cuento, un capítulo, un ensayo, dos entrevistas imaginadas y un careo, sobre la misma regla</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco primeros <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, y el sexto es un careo escrito por la casa sobre una disputa real, y las dos entrevistas son <strong>imaginadas: los encuentros nunca ocurrieron</strong>. Las conversaciones con Donald O. Hebb, y entre Jesús Quintero y Antonio Gala, son invención del Proyecto Educativo F.A.R.O., que se declara como pastiche. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala','debate'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las seis lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las seis lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🏺 Ruta del Barro Vivo · Etapa 1 de 6</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las seis lecturas</h1><div class="tipo">La regla de Hebb, bien contada · 30 de comprensión lectora, 12 de completar y 12 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los seis textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco primeros son <strong>ejercicios de estilo de la casa</strong>: no son obra de Borges, Cervantes ni Harari, y las dos entrevistas son imaginadas (los encuentros nunca ocurrieron). El sexto es un <strong>careo</strong> sobre una disputa real, con los turnos firmados por papeles y no por personas.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (30 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (12 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (12 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue produciendo y corrigiendo!','¡Muy buen trabajo!','¡Ya citas el postulado entero!','¡Distingues junto de participar!','¡Diseñador de práctica que sí cablea!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏺 ¡'+name+' completó la Etapa 1 de la Ruta del Barro Vivo (La regla de Hebb, bien contada)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

